span.t-attf-class:
badge rounded-pill #{
                                            'text-bg-secondary' if order.state == 'draft' else
                                            'text-bg-warning'   if order.state == 'submitted' else
                                            'text-bg-primary'   if order.state == 'approved' else
                                            'text-bg-success'   if order.state in ('ready_pickup','ready_ship') else
                                            'text-bg-info'}

t.script:
(function () {
    'use strict';

    /* ── MODAL ────────────────────────────────────────────────────── */
    var _modal = null;
    function getModal() {
        if (!_modal) _modal = new bootstrap.Modal(document.getElementById('jobInfoModal'), {backdrop:'static', keyboard:false});
        return _modal;
    }

    (document.readyState === 'loading')
        ? document.addEventListener('DOMContentLoaded', function(){ getModal().show(); })
        : getModal().show();

    document.getElementById('btn_start_quote').addEventListener('click', function () {
        var jn = document.getElementById('modal_job_name').value.trim();
        if (!jn) {
            document.getElementById('modal_job_name').classList.add('is-invalid');
            document.getElementById('modal_job_name').focus();
            return;
        }
        document.getElementById('modal_job_name').classList.remove('is-invalid');

        var cSel = document.getElementById('modal_client');
        var cId  = cSel.value;
        var cNm  = cId ? cSel.options[cSel.selectedIndex].text.trim() : '';
        var po   = document.getElementById('modal_po_number').value.trim();
        var mk   = document.getElementById('modal_job_markup').value || '0';

        document.getElementById('field_job_name').value   = jn;
        document.getElementById('field_po_number').value  = po;
        document.getElementById('field_client_id').value  = cId;
        document.getElementById('field_job_markup').value = mk;

        document.getElementById('summary_job_name').textContent = jn;
        setWrap('summary_client_wrap', 'summary_client', cNm);
        setWrap('summary_po_wrap', 'summary_po', po);

        getModal().hide();
    });

    function setWrap(wrapId, textId, val) {
        var w = document.getElementById(wrapId);
        document.getElementById(textId).textContent = val;
        w.classList.toggle('d-none', !val);
    }

    // New client inline
    document.getElementById('btn_new_client').addEventListener('click', function () {
        document.getElementById('new_client_form').classList.toggle('d-none');
        document.getElementById('new_client_name').focus();
    });
    document.getElementById('btn_cancel_new_client').addEventListener('click', function () {
        document.getElementById('new_client_form').classList.add('d-none');
        document.getElementById('new_client_name').value = '';
    });
    document.getElementById('btn_save_new_client').addEventListener('click', function () {
        var name = document.getElementById('new_client_name').value.trim();
        if (!name) return;
        var btn = this; btn.disabled = true;
        fetch('/my/clients/create_ajax', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jsonrpc:'2.0', method:'call', params:{name:name}}),
        })
        .then(function(r){return r.json();})
        .then(function(res){
            if (res.result && res.result.id) {
                var c = res.result;
                var opt = new Option(c.name, c.id, true, true);
                opt.dataset.markup = c.markup;
                document.getElementById('modal_client').add(opt);
                document.getElementById('new_client_form').classList.add('d-none');
                document.getElementById('new_client_name').value = '';
            }
            btn.disabled = false;
        })
        .catch(function(){ btn.disabled = false; });
    });

    document.getElementById('door_order_form').addEventListener('submit', function (e) {
        if (!document.getElementById('field_job_name').value.trim()) {
            e.preventDefault(); getModal().show(); return;
        }
        if (!document.getElementById('field_glass_type_id').value) {
            e.preventDefault();
            document.getElementById('thickness_btns').scrollIntoView({behavior:'smooth', block:'center'});
            alert('Please select a glass thickness and tint.');
        }
    });

    /* ── GLASS CASCADE ────────────────────────────────────────────── */
    var glassData = JSON.parse(document.getElementById('glass_types_data').textContent || '[]');

    // Thickness labels for the dropdown
    var thickLabels = {'5/16':'5/16" Laminated','7/16':'7/16" Laminated','13/16':'13/16" Insulated Laminated'};

    function buildThicknessDropdown() {
        var sel    = document.getElementById('thickness_select');
        var notice = document.getElementById('glass_empty_notice');
        var seen   = {}; var thicknesses = [];
        glassData.forEach(function(g){
            if (!seen[g.thickness]){ seen[g.thickness]=1; thicknesses.push(g.thickness); }
        });
        if (!thicknesses.length) { notice.classList.remove('d-none'); return; }
        notice.classList.add('d-none');
        thicknesses.forEach(function(th){
            var opt = document.createElement('option');
            opt.value = th;
            opt.textContent = thickLabels[th] || th;
            sel.appendChild(opt);
        });
        sel.addEventListener('change', function(){
            var th = this.value;
            document.getElementById('composition_section').style.display = 'none';
            document.getElementById('interlayer_section').style.display  = 'none';
            document.getElementById('glass_type_btns').innerHTML = '';
            document.getElementById('field_glass_type_id').value = '';
            if (th) buildCompositionList(th);
        });
    }

    function buildCompositionList(th) {
        var types     = glassData.filter(function(g){ return g.thickness === th; });
        var section   = document.getElementById('composition_section');
        var container = document.getElementById('glass_type_btns');
        container.innerHTML = '';
        document.getElementById('field_glass_type_id').value = '';
        document.getElementById('interlayer_section').style.display = 'none';
        if (!types.length) return;
        section.style.display = '';
        types.forEach(function(gt){
            var inp = document.createElement('input');
            inp.type='radio'; inp.className='btn-check';
            inp.name='_glass_type'; inp.id='gt_'+gt.id; inp.value=gt.id;
            inp.addEventListener('change', function(){
                document.getElementById('field_glass_type_id').value = gt.id;
                document.getElementById('interlayer_section').style.display = '';
                updatePrice();
            });
            var lbl = document.createElement('label');
            lbl.className = 'btn btn-outline-secondary text-start py-2 px-3 w-100';
            lbl.setAttribute('for', 'gt_'+gt.id);
            lbl.style.fontFamily = 'monospace';
            lbl.style.fontSize   = '0.82rem';
            lbl.textContent      = gt.name;
            container.appendChild(inp);
            container.appendChild(lbl);
        });
    }

    // PVB color change triggers price recalc
    document.getElementById('interlayer_id').addEventListener('change', function(){
        updatePrice();
    });

    buildThicknessDropdown();

    /* ── MISC ITEMS ───────────────────────────────────────────────── */
    var miscRows = [];

    function fmtM(n){ return '$'+(parseFloat(n)||0).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g,','); }

    function renderMiscTable() {
        var tbody = document.getElementById('misc_tbody');
        var emptyRow = document.getElementById('misc_empty_row');
        tbody.innerHTML = '';
        emptyRow.style.display = miscRows.length ? 'none' : '';

        miscRows.forEach(function (row, idx) {
            var tr = document.createElement('tr');

            var td1 = document.createElement('td'); td1.className = 'ps-3';
            var i1 = document.createElement('input');
            i1.type='text'; i1.className='form-control form-control-sm';
            i1.value = row.description||''; i1.placeholder='Item description';
            i1.dataset.idx=idx; i1.dataset.field='description';
            td1.appendChild(i1); tr.appendChild(td1);

            var td2 = document.createElement('td');
            var i2 = document.createElement('input');
            i2.type='number'; i2.className='form-control form-control-sm text-center';
            i2.value=row.qty; i2.min=1; i2.style.width='70px';
            i2.dataset.idx=idx; i2.dataset.field='qty';
            td2.appendChild(i2); tr.appendChild(td2);

            var td3 = document.createElement('td');
            var ig = document.createElement('div'); ig.className='input-group input-group-sm';
            var sp = document.createElement('span'); sp.className='input-group-text'; sp.textContent='$';
            var i3 = document.createElement('input');
            i3.type='number'; i3.className='form-control form-control-sm';
            i3.value=row.unit_price; i3.min=0; i3.step='0.01';
            i3.dataset.idx=idx; i3.dataset.field='unit_price';
            ig.appendChild(sp); ig.appendChild(i3); td3.appendChild(ig); tr.appendChild(td3);

            var td4 = document.createElement('td');
            td4.className='text-end pe-2 align-middle misc-total';
            td4.textContent=fmtM(row.qty*row.unit_price); tr.appendChild(td4);

            var td5 = document.createElement('td'); td5.className='align-middle text-center';
            var btnD = document.createElement('button');
            btnD.type='button'; btnD.className='btn btn-sm btn-link text-danger p-0';
            btnD.textContent='✕'; btnD.dataset.idx=idx;
            td5.appendChild(btnD); tr.appendChild(td5);

            tbody.appendChild(tr);
        });

        tbody.querySelectorAll('input[data-field]').forEach(function(inp){
            inp.addEventListener('input', function(){
                var i=parseInt(inp.dataset.idx,10); var f=inp.dataset.field;
                miscRows[i][f]=(f==='description')?inp.value:(parseFloat(inp.value)||0);
                var tots=tbody.querySelectorAll('.misc-total');
                if(tots[i]) tots[i].textContent=fmtM(miscRows[i].qty*miscRows[i].unit_price);
                saveMiscJson(); updatePrice();
            });
        });
        tbody.querySelectorAll('.btn-link.text-danger').forEach(function(btn){
            btn.addEventListener('click', function(){
                miscRows.splice(parseInt(btn.dataset.idx,10),1);
                renderMiscTable(); saveMiscJson(); updatePrice();
            });
        });
    }

    function saveMiscJson(){
        document.getElementById('misc_items_json').value=JSON.stringify(miscRows);
    }

    document.getElementById('btn_add_misc').addEventListener('click', function(){
        miscRows.push({description:'',qty:1,unit_price:0});
        renderMiscTable();
        var inps=document.querySelectorAll('#misc_tbody input[data-field="description"]');
        if(inps.length) inps[inps.length-1].focus();
    });

    renderMiscTable();

    /* ── PRICE CALCULATOR ─────────────────────────────────────────── */
    var _priceTimer = null;

    function getLitesValue() {
        var checked = document.querySelector('input[name="lites"]:checked');
        return checked ? parseInt(checked.value, 10) : 1;
    }

    function getFormData() {
        return {
            frame_width:     parseFloat(document.getElementById('frame_width').value)||0,
            frame_height:    parseFloat(document.getElementById('frame_height').value)||0,
            lites:           getLitesValue(),
            glass_type_id:   parseInt(document.getElementById('field_glass_type_id').value,10)||0,
            interlayer_id:   parseInt(document.getElementById('interlayer_id').value,10)||0,
            quantity:        parseInt(document.getElementById('quantity').value,10)||1,
            series:          (document.querySelector('input[name="series"]:checked')||{value:'1200'}).value,
            design_pressure: (document.querySelector('input[name="design_pressure"]:checked')||{value:'dp20'}).value,
            frame_finish_id: parseInt((document.querySelector('input[name="frame_finish_id"]:checked')||{value:'0'}).value,10)||0,
            trim_type:       document.getElementById('trim_type').value,
            include_reinforcement: document.getElementById('include_reinforcement').checked,
            motor_id:        parseInt(document.getElementById('motor_id').value,10)||0,
            job_markup:      parseFloat(document.getElementById('field_job_markup').value)||0,
            misc_total:      miscRows.reduce(function(s,r){return s+((parseFloat(r.qty)||0)*(parseFloat(r.unit_price)||0));},0),
        };
    }

    function fmt(n){ return '$'+parseFloat(n).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g,','); }

    function updatePrice() {
        var data = getFormData();
        if (!data.frame_width || !data.frame_height || !data.glass_type_id) return;

        // Auto-enforce lites for wide doors
        if (data.frame_width > 144 && data.lites < 2) {
            var l2 = document.getElementById('lites_2');
            if (l2) l2.checked = true;
            data.lites = 2;
            document.getElementById('lites_warning').classList.remove('d-none');
        }

        clearTimeout(_priceTimer);
        _priceTimer = setTimeout(function(){
            fetch('/my/doors/compute_price', {
                method:'POST',
                headers:{'Content-Type':'application/json'},
                body:JSON.stringify({jsonrpc:'2.0',method:'call',params:data}),
            })
            .then(function(r){return r.json();})
            .then(function(res){
                if (!res.result || res.result.error) return;
                var r = res.result;
                document.getElementById('prev_panels').textContent  = r.num_panels;
                document.getElementById('prev_glass_w').textContent = r.glass_width + '"';
                document.getElementById('prev_glass_h').textContent = r.glass_height + '"';
                document.getElementById('prev_weight').textContent  = r.door_weight + ' lbs';
                document.getElementById('prev_dp').textContent      = r.design_pressure || '—';
                enforceTrackByWeight(r.door_weight);
                document.getElementById('door_preview').classList.remove('d-none');
                document.getElementById('price_unit').textContent  = fmt(r.unit_price);
                document.getElementById('price_total').textContent = fmt(r.total_price);
                document.getElementById('price_note').textContent  = 'Includes all markups';
                // If system forced reinforcement, check the box
                if (r.reinf_forced) {
                    document.getElementById('include_reinforcement').checked = true;
                    document.getElementById('reinf_required_note').classList.remove('d-none');
                }
            });
        }, 400);
    }

    // Series 1800 → force reinforcement + show notice
    function onSeriesChange() {
        var s = (document.querySelector('input[name="series"]:checked')||{value:'1200'}).value;
        var is1800 = (s === '1800');
        var reinf = document.getElementById('include_reinforcement');
        var notice = document.getElementById('series_1800_notice');
        var reinfNote = document.getElementById('reinf_required_note');
        if (is1800) {
            reinf.checked = true;
            reinf.disabled = true;
            notice.classList.remove('d-none');
            reinfNote.classList.remove('d-none');
        } else {
            reinf.disabled = false;
            notice.classList.add('d-none');
        }
        updatePrice();
    }
    document.querySelectorAll('input[name="series"]').forEach(function(el){
        el.addEventListener('change', onSeriesChange);
    });
    onSeriesChange(); // run once on load

    // Wide-door auto-reinforcement
    document.getElementById('frame_width').addEventListener('input', function(){
        var w = parseFloat(this.value)||0;
        document.getElementById('lites_warning').classList.toggle('d-none', w <= 144);
        if (w > 194) {
            document.getElementById('include_reinforcement').checked = true;
            document.getElementById('reinf_required_note').classList.remove('d-none');
        }
    });

    // Wire all price-affecting controls
    ['frame_width','frame_height','interlayer_id','trim_type',
     'include_reinforcement','motor_id','quantity'].forEach(function(id){
        var el=document.getElementById(id);
        if (el) {
            el.addEventListener('change', updatePrice);
            if (el.type==='number'||el.tagName==='INPUT') el.addEventListener('input', updatePrice);
        }
    });
    document.querySelectorAll('input[name="lites"],input[name="frame_finish_id"],'
        +'input[name="track_size"],input[name="track_radius"],'
        +'input[name="hardware_color"]').forEach(function(el){
        el.addEventListener('change', updatePrice);
    });

    // Track type dropdown — show/hide high lift amount field
    (function(){
        var sel     = document.getElementById('track_type');
        var hlSec   = document.getElementById('high_lift_section');
        var hlInput = document.getElementById('high_lift_amount');
        function onTrackChange() {
            var isHL = sel.value === 'high_lift';
            hlSec.style.display = isHL ? '' : 'none';
            if (!isHL) hlInput.value = '';
        }
        sel.addEventListener('change', onTrackChange);
        onTrackChange(); // run once on load
    })();

    // Track size ↔ radius + weight constraints
    var _trackSize2    = document.getElementById('track_2inch');
    var _trackSize3    = document.getElementById('track_3inch');
    var _trackR12      = document.getElementById('track_r12');
    var _trackR15      = document.getElementById('track_r15');
    var _trackR12Lbl   = document.getElementById('track_r12_label');
    var _radiusNote    = document.getElementById('radius_note');
    var _weightNote    = document.getElementById('track_weight_note');
    var _weightForced3 = false; // true when 3” is locked by door weight

    function applyTrackSizeConstraints() {
        var is3inch = _trackSize3.checked;
        if (is3inch) {
            _trackR12.checked = false;
            _trackR12.disabled = true;
            _trackR12Lbl.classList.add('disabled');
            _trackR15.checked = true;
            _radiusNote.textContent = '12” radius not available with 3” track.';
        } else {
            _trackR12.disabled = false;
            _trackR12Lbl.classList.remove('disabled');
            _radiusNote.textContent = '12” standard · 15” for larger / heavier doors';
        }
    }

    function enforceTrackByWeight(weightLbs) {
        if (weightLbs > 500) {
            if (!_weightForced3) {
                _weightForced3 = true;
                _trackSize2.checked  = false;
                _trackSize2.disabled = true;
                _trackSize3.checked  = true;
                _weightNote.classList.remove('d-none');
                applyTrackSizeConstraints();
            }
        } else {
            if (_weightForced3) {
                _weightForced3 = false;
                _trackSize2.disabled = false;
                _weightNote.classList.add('d-none');
                applyTrackSizeConstraints();
            }
        }
    }

    _trackSize2.addEventListener('change', function(){ applyTrackSizeConstraints(); updatePrice(); });
    _trackSize3.addEventListener('change', function(){ applyTrackSizeConstraints(); updatePrice(); });
    applyTrackSizeConstraints(); // run once on load

})();

span.t-attf-class:
badge fs-6 #{
                        'text-bg-secondary' if order.state == 'draft' else
                        'text-bg-warning'   if order.state == 'submitted' else
                        'text-bg-primary'   if order.state == 'approved' else
                        'text-bg-success'   if order.state in ('ready_pickup','ready_ship') else
                        'text-bg-info'}

t.script:
(function () {
    document.querySelectorAll('.btn-edit-client').forEach(function (btn) {
        btn.addEventListener('click', function () {
            document.getElementById('clientModalTitle').textContent = 'Edit Client';
            document.getElementById('edit_client_id').value = btn.dataset.id;
            document.getElementById('edit_name').value      = btn.dataset.name;
            document.getElementById('edit_markup').value    = btn.dataset.markup;
            document.getElementById('edit_phone').value     = btn.dataset.phone;
            document.getElementById('edit_email').value     = btn.dataset.email;
        });
    });
    function resetModal() {
        document.getElementById('clientModalTitle').textContent = 'New Client';
        ['edit_client_id','edit_name','edit_phone','edit_email'].forEach(function(id){
            document.getElementById(id).value = '';
        });
        document.getElementById('edit_client_id').value = '0';
        document.getElementById('edit_markup').value    = '0';
    }
    var a = document.getElementById('btn_add_client');
    var b = document.getElementById('btn_add_client_empty');
    if (a) a.addEventListener('click', resetModal);
    if (b) b.addEventListener('click', resetModal);
})();
